#!/usr/bin/env python3
"""Whole national2021 reported SPO/VPO organization/branch programmes, notcampuscounts."""
from pathlib import Path
import sys,json,re,hashlib,datetime
import pandas as pd,numpy as np,bs4
HERE=Path(__file__).resolve().parent;BASE=HERE.parent;sys.path.insert(0,str(BASE/'education'))
from build_school_features import link,norm
SECTORS=['vpo','spo'];INDUSTRIES=['mathematics_natural','engineering_technology','health_medicine','agriculture','social_sciences','education_pedagogy','humanities','arts_culture','defence_security']
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def parse_number(raw):
 v=re.sub(r'\s+','',raw).replace(',','.')
 return float(v)if re.fullmatch(r'\d+(\.\d+)?',v)else None

def main():
 acq=json.loads((HERE/'official_monitoring2021_acquisition.json').read_text());assert len(acq['files'])==16 and all(r['status']=='ACQUIRED'for r in acq['files']);rows=[];controls=[]
 for f in acq['files']:
  p=Path(f['file']);assert sha(p)==f['sha256'];s=bs4.BeautifulSoup(p.read_bytes(),'html.parser');selected=s.select('td.inst[id]');control={'sector':f['sector'],'federal_district_source_id':f['fd'],'source_url':f['url'],'actual_reporting_unit_rows':len(selected),'acquisition_reporting_unit_rows':f['institution_rows']};controls.append(control)
  for td in selected:
   a=td.select_one('a[href]');rid=td.get('id');city=td.get('city');coord=td.get('coordinates','');nums=re.findall(r'-?\d+(?:\.\d+)?',coord);lon,lat=(map(float,nums[:2])if len(nums)>=2 else(np.nan,np.nan));adr=td.select_one('div.adr');paras=adr.select('p')if adr else[];address=paras[1].get_text(' ',strip=True)if len(paras)>1 else None;tr=td.find_parent('tr');cells=tr.select('td.dkont')[:9]if tr else[];assert len(cells)==9,(f['sector'],rid,len(cells));raw=[c.get_text(' ',strip=True)for c in cells];vals=[parse_number(v)for v in raw]
   row={'reporting_unit_key':f'miccedu2022_{f["sector"]}:{rid}','source_entity_id':rid,'education_sector':f['sector'],'reporting_unit_name':a.get_text(' ',strip=True),'source_reported_city':city,'source_reported_address':address,'source_coordinates_raw':coord,'lon':lon,'lat':lat,'source_reporting_year':2022,'source_reference_data_year':2021,'source_snapshot':'monitoring2022data2021','federal_district_source_id':f['fd'],'source_url':f['url'],'individual_profile_url':f'https://monitoring.miccedu.ru/iam/2022/_{f["sector"]}/inst.php?id={rid}','source_file':str(p),'source_file_sha256':f['sha256'],'source_row_locator':f'td.inst[id={rid}]','raw_row_html_sha256':hashlib.sha256(str(tr).encode()).hexdigest(),'reported_branch_name_signal':'филиал'in a.get_text(' ',strip=True).lower(),'observed_programme_industries_positive':sum(v is not None and v>0 for v in vals),'known_positive_weighted_contingent_partial_sum':sum(v for v in vals if v is not None)if any(v is not None for v in vals)else None,'physical_campus_or_student_seat_census':False,'reported_organization_address_not_proven_teaching_site':True,'institution_students_not_allocated_to_single_settlement':True,'source_blank_numeric_cells_preserved_unknown':True,'all_nine_raw_weighted_contingent_cells_json':json.dumps(raw,ensure_ascii=False)}
   for industry,value,rawcell,c in zip(INDUSTRIES,vals,raw,cells):row[f'weighted_contingent_{industry}']=value;row[f'raw_contingent_{industry}']=rawcell;row[f'blank_zero_rendering_style_{industry}']=not bool(rawcell)and bool(re.search(r'background-size:\s*0%',c.get('style','')))
   rows.append(row)
 d=pd.DataFrame(rows);assert d.reporting_unit_key.is_unique
 for sec,expected in [('vpo',1208),('spo',4572)]:assert d.education_sector.eq(sec).sum()==expected
 axis=pd.read_parquet(BASE/'axis/full_settlement_axis.parquet');loc=d[d.lat.notna()&d.lon.notna()].copy();loc['tags_json']=loc.source_reported_city.map(lambda c:json.dumps({'addr:city':c},ensure_ascii=False));mapped=link(loc,axis)
 # Retain institutionaddressidentity as its own relation; never renameit
 # acceptedphysicalsite or put it intoOSMphysicalcampuscounts.
 lc=mapped[['reporting_unit_key','baseline_uid','candidate_uid','link_status','linked_distance_km','nearest_uid_unaccepted','nearest_distance_km','second_nearest_distance_km']].rename(columns={'baseline_uid':'reported_org_locality_explicit_uid','candidate_uid':'reported_org_spatial_candidate_uid','link_status':'reported_org_address_identity_status'})
 d=d.merge(lc,on='reporting_unit_key',how='left',validate='one_to_one');d['reported_org_address_identity_status']=d.reported_org_address_identity_status.fillna('no_source_coordinates_retained_unlinked');d['reported_federal_city']=d.source_reported_city.fillna('').map(norm).str.replace(r'^(г|город)\s+','',regex=True).isin(['москва','санкт петербург','санктпетербург','севастополь'])
 d['reported_org_explicit_target_population_scope']=d.reported_org_locality_explicit_uid.map(axis.set_index('id').population_scope)
 d['reported_org_explicit_target_axis_kind']=d.reported_org_locality_explicit_uid.map(axis.set_index('id').axis_kind)
 d['reported_org_explicit_target_is_ordinary_settlement']=d.reported_org_explicit_target_population_scope.eq('settlement')
 d.to_parquet(HERE/'official_monitoring2021_reporting_organizations.parquet',index=False)
 features=axis[['id','population_scope','axis_kind']].copy()
 for sec in SECTORS:
  z=d[d.education_sector.eq(sec)&d.reported_org_locality_explicit_uid.notna()];features[f'official2021_{sec}_reported_organization_locality_witness_count']=features.id.map(z.groupby('reported_org_locality_explicit_uid').size()).fillna(0).astype('int32');positive=z[z.observed_programme_industries_positive.gt(0)];features[f'official2021_{sec}_positive_programme_reporting_unit_count']=features.id.map(positive.groupby('reported_org_locality_explicit_uid').size()).fillna(0).astype('int32')
  for industry in INDUSTRIES:
   q=z[z[f'weighted_contingent_{industry}'].gt(0)];features[f'official2021_{sec}_{industry}_positive_reporting_units']=features.id.map(q.groupby('reported_org_locality_explicit_uid').size()).fillna(0).astype('int32')
 features['official_reporting_units_are_not_physical_campuses']=True;features['source_absence_means_unknown_function']=True;features['source_reference_data_year']=2021;features['source_reporting_year']=2022;features.to_parquet(HERE/'official_monitoring2021_locality_features.parquet',index=False)
 # Sameentity IDs canoccur acrossSPO/VPO; preservebothprogramme records and
 # publish overlapverification, ratherthanaddthem as twophysicalcampuses.
 v=d[d.education_sector.eq('vpo')];s=d[d.education_sector.eq('spo')];over=v.merge(s,on='source_entity_id',suffixes=('_vpo','_spo'),validate='one_to_one');over['same_normalized_name']=over.reporting_unit_name_vpo.map(norm).eq(over.reporting_unit_name_spo.map(norm));over['same_coordinates']=over.lat_vpo.eq(over.lat_spo)&over.lon_vpo.eq(over.lon_spo);over.to_parquet(HERE/'official_monitoring2021_cross_sector_overlap.parquet',index=False)
 pd.DataFrame(controls).to_csv(HERE/'official_monitoring2021_national_source_controls.csv',index=False)
 summary=[]
 for sec in SECTORS:
  z=d[d.education_sector.eq(sec)];summary.append({'education_sector':sec,'national_published_reporting_unit_control':1208 if sec=='vpo' else 4572,'downloaded_reporting_unit_rows':len(z),'positive_programme_weighted_contingent_units':int(z.observed_programme_industries_positive.gt(0).sum()),'valid_reported_coordinates':int(z.lat.notna().sum()),'explicit_locality_matched_reporting_units':int(z.reported_org_locality_explicit_uid.notna().sum()),'explicit_locality_unique_axis_entities':int(z.reported_org_locality_explicit_uid.nunique()),'spatial_candidate_reporting_units':int(z.reported_org_spatial_candidate_uid.notna().sum()),'reported_federal_city_units':int(z.reported_federal_city.sum()),'branch_name_signals':int(z.reported_branch_name_signal.sum())})
 pd.DataFrame(summary).to_csv(HERE/'official_monitoring2021_inventory.csv',index=False)
 receipt={'status':'ACTUALLY_ACQUIRED_ENTIRE_NATIONAL_REPORTED_SPO_VPO2021_PROGRAMME_INVENTORY_PENDING_INDEPENDENT_REVIEW','created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'source_name':'OfficialMICCEDU/MIREA/Ministriespublicmonitoring2022archive(data2021)','source_home_urls':['https://monitoring.miccedu.ru/?m=vpo&year=2022','https://monitoring.miccedu.ru/?m=spo&year=2022'],'year_basis':'Officialarchive explicitly labelsmonitoring2022 asdata2021; tables describe2021 resourceactivity. Reportyear isnotdatareferenceyear.','attribution_required':'При использовании материалов сайта ссылка на сайт www.miccedu.ru обязательна','source_files_sha256':{f['file']:f['sha256']for f in acq['files']},'source_national_indexes_sha256':{str(HERE/'sources'/f'monitoring2022_{s}.html'):sha(HERE/'sources'/f'monitoring2022_{s}.html')for s in SECTORS},'coverage':summary,'reporting_units_total':len(d),'source_participating_reporting_units_not_complete_census':True,'source_excludes':'Defence/security/law-enforcementorganizations andnonreporters asofficialfootnote','source_function_grain':'Organizationorbranchreportswithprogramme-weightedstudentcontingent; reportedorganizationaddressnotprovenphysicalteachingcampus','weighted_student_contingent_is_not_capacity_or_actual_headcount':True,'students_allocated_to_np':False,'physical_osm_counts_modified':False,'unknown_numeric_cells_imputed_zero':False,'cross_sector_same_entity_ids':len(over),'cross_sector_same_names':int(over.same_normalized_name.sum()),'cross_sector_same_coordinates':int(over.same_coordinates.sum()),'author_read_model_assignments_or_agreement':False,'axis_sha256':sha(BASE/'axis/full_settlement_axis.parquet'),'linkage_code_sha256':sha(BASE/'education/build_school_features.py'),'code_sha256':sha(Path(__file__)),'output_files_sha256':{p.name:sha(p)for p in [HERE/'official_monitoring2021_reporting_organizations.parquet',HERE/'official_monitoring2021_locality_features.parquet',HERE/'official_monitoring2021_cross_sector_overlap.parquet',HERE/'official_monitoring2021_national_source_controls.csv',HERE/'official_monitoring2021_inventory.csv']}}
 (HERE/'official_monitoring2021_build_receipt.json').write_text(json.dumps(receipt,ensure_ascii=False,indent=2));print(pd.DataFrame(summary).to_string(index=False));print('cross_sector_overlap',len(over),'nameagree',int(over.same_normalized_name.sum()))
if __name__=='__main__':main()
